<template>
  <section class="admin-console">
    <aside class="admin-rail">
      <button class="admin-logo" @click="selectTab('overview')"><span>拾</span><div><strong>拾光集市</strong><small>管理控制台</small></div></button>
      <div class="admin-user"><span class="admin-user-avatar">管</span><div><strong>{{ userName }}</strong><small>管理员账号</small></div><i>•••</i></div>
      <p class="rail-title">工作空间</p>
      <button v-for="item in menus" :key="item.key" :class="['rail-item',{active:tab===item.key}]" @click="selectTab(item.key)"><span class="rail-icon">{{ item.icon }}</span><span>{{ item.label }}</span><b v-if="item.badge">{{ item.badge }}</b></button>
      <div class="rail-bottom"><button class="rail-item" @click="$emit('back')"><span class="rail-icon">↩</span><span>返回用户端</span></button><small>Campus Market · Admin</small></div>
    </aside>
    <main class="admin-content">
      <PageBanner :page="tab" admin @action="selectTab"/>
      <header class="admin-topbar"><div><p class="crumb">拾光集市 / {{ activeMenu.label }}</p><h1>{{ activeMenu.label }}</h1><p>{{ activeMenu.description }}</p></div><div class="top-actions"><span class="sync-dot"></span><span>数据已同步</span><button @click="loadCurrent">↻ 刷新</button><div class="top-user"><span>{{ userName.slice(0,1) }}</span>{{ userName }}</div></div></header>
      <div v-if="loading" class="admin-loading">正在加载管理数据...</div>
      <template v-else>
        <section v-if="tab==='overview'" class="workspace"><div class="stats"><div class="stat-card"><div class="stat-icon peach">▦</div><span>商品总数</span><strong>{{ stats.goods }}</strong><small>平台全部商品</small></div><div class="stat-card"><div class="stat-icon green">✓</div><span>在售商品</span><strong>{{ stats.onSale }}</strong><small>当前可以交易</small></div><div class="stat-card"><div class="stat-icon orange">◇</div><span>待处理事项</span><strong>{{ Number(stats.pendingOrders||0)+Number(stats.pendingReports||0)+Number(stats.pendingWants||0) }}</strong><small>订单 {{stats.pendingOrders||0}} · 举报 {{stats.pendingReports||0}} · 求购 {{stats.pendingWants||0}}</small></div><div class="stat-card"><div class="stat-icon blue">♙</div><span>活跃用户</span><strong>{{ stats.activeUsers }}</strong><small>状态正常的账号</small></div></div><div class="two-columns"><div class="card-block attention"><div class="block-header"><div><h2>需要你处理</h2><p>按优先级排列的后台事项</p></div><span class="attention-count">{{ Number(stats.pendingOrders||0)+Number(stats.pendingReports||0)+Number(stats.pendingWants||0) }} 项</span></div><button class="attention-row" @click="selectTab('orders')"><span class="attention-icon orange">◇</span><div><strong>{{ stats.pendingOrders||0 }} 个购买意向订单</strong><small>查看订单状态并确认交易完成</small></div><i>→</i></button><button class="attention-row" @click="selectTab('reports')"><span class="attention-icon red">!</span><div><strong>{{ stats.pendingReports||0 }} 条待处理举报</strong><small>检查商品内容和用户行为</small></div><i>→</i></button><button class="attention-row" @click="selectTab('goods')"><span class="attention-icon gray">▣</span><div><strong>{{ stats.offShelf||0 }} 件已下架商品</strong><small>查看下架原因和恢复状态</small></div><i>→</i></button></div><div class="card-block distribution"><div class="block-header"><div><h2>平台状态</h2><p>当前业务数据分布</p></div><span class="live-label"><i></i> LIVE</span></div><div class="donut-wrap"><div class="donut"><strong>{{ stats.goods }}</strong><span>商品总数</span></div><div class="legend"><span><i class="dot green-dot"></i>在售 <b>{{stats.onSale}}</b></span><span><i class="dot gray-dot"></i>下架 <b>{{stats.offShelf}}</b></span><span><i class="dot orange-dot"></i>订单 <b>{{stats.orders}}</b></span></div></div></div></div><div class="card-block recent"><div class="block-header"><div><h2>最近发布的商品</h2><p>最新进入平台的商品记录</p></div><button @click="selectTab('goods')">查看全部 →</button></div><div class="recent-grid"><div v-for="item in goods" :key="item.id" class="recent-item"><ProductImage :src="item.imageUrl" :alt="item.title" lazy/><div><strong>{{ item.title }}</strong><small>{{ item.sellerName }} · {{ item.category }}</small></div><b>¥{{Number(item.price).toFixed(2)}}</b></div></div></div></section>
        <section v-else-if="tab==='goods'" class="workspace"><div class="section-toolbar"><div><h2>商品审核</h2><p>管理平台商品状态和违规内容</p></div><div class="toolbar-controls"><div class="search-box">⌕<input v-model="goodsKeyword" placeholder="搜索商品或卖家"/></div><el-select v-model="goodsStatus" placeholder="全部状态" clearable><el-option label="在售" value="ON_SALE"/><el-option label="已下架" value="OFF_SHELF"/><el-option label="已预订" value="RESERVED"/></el-select></div></div><div class="table-card"><div class="table-caption">商品列表 <span>共 {{adminTotals.goods}} 条</span></div><div class="data-row data-head goods-columns"><span>商品信息</span><span>卖家</span><span>价格</span><span>状态</span><span>操作</span></div><div v-for="item in filteredGoods" :key="item.id" class="data-row goods-columns"><div class="product-cell"><ProductImage :src="item.imageUrl" :alt="item.title" lazy/><div><strong>{{item.title}}</strong><small>{{item.category}} · {{item.location}}</small></div></div><span>{{item.sellerName}}</span><b class="price">¥{{Number(item.price).toFixed(2)}}</b><el-tag size="small" :type="item.status==='ON_SALE'?'success':'info'">{{statusLabel(item.status)}}</el-tag><button class="row-action" @click="toggleGoods(item)">{{item.status==='ON_SALE'?'下架':'恢复上架'}}</button></div></div></section>
        <section v-else-if="tab==='users'" class="workspace"><div class="section-toolbar"><div><h2>用户管理</h2><p>维护账号状态和平台角色</p></div><div class="toolbar-controls"><div class="search-box">⌕<input v-model="userKeyword" placeholder="搜索用户名或昵称"/></div></div></div><div class="table-card"><div class="table-caption">用户列表 <span>共 {{adminTotals.users}} 个账号</span></div><div class="data-row data-head user-columns"><span>用户</span><span>用户名</span><span>角色</span><span>状态</span><span>操作</span></div><div v-for="user in filteredUsers" :key="user.id" class="data-row user-columns"><div class="product-cell"><span class="user-avatar">{{user.nickname?.slice(0,1)}}</span><div><strong>{{user.nickname}}</strong><small>账号 #{{user.id}}</small></div></div><span>{{user.username}}</span><el-tag size="small" :type="user.role==='ADMIN'?'warning':'info'">{{user.role==='ADMIN'?'管理员':'普通用户'}}</el-tag><el-tag size="small" :type="user.status===1?'success':'danger'">{{user.status===1?'正常':'已禁用'}}</el-tag><button class="row-action" :disabled="user.role==='ADMIN'" @click="toggleUser(user)">{{user.status===1?'禁用账号':'恢复账号'}}</button></div></div></section>
        <section v-else-if="tab==='orders'" class="workspace"><div class="section-toolbar"><div><h2>订单监管</h2><p>跟踪购买意向和交易完成情况</p></div><el-select v-model="orderStatus" placeholder="全部状态" clearable><el-option label="待确认" value="PENDING"/><el-option label="已完成" value="COMPLETED"/><el-option label="已取消" value="CANCELLED"/></el-select></div><div class="table-card"><div class="table-caption">订单列表 <span>共 {{adminTotals.orders}} 条</span></div><div class="data-row data-head order-columns"><span>订单信息</span><span>买家</span><span>卖家</span><span>金额</span><span>状态</span></div><div v-for="order in filteredOrders" :key="order.id" class="data-row order-columns"><div><strong>{{order.title}}</strong><small>订单 #{{order.id}} · {{order.location}}</small></div><span>{{order.buyerName}}</span><span>{{order.sellerName}}</span><b class="price">¥{{Number(order.price).toFixed(2)}}</b><div class="order-action"><el-tag size="small" :type="order.status==='PENDING'?'warning':order.status==='COMPLETED'?'success':'info'">{{orderStatusLabel(order.status)}}</el-tag><button v-if="order.status==='PENDING'" class="row-action" @click="completeOrder(order)">标记完成</button></div></div></div></section>
        <section v-else-if="tab==='messages'" class="workspace"><div class="section-toolbar"><div><h2>留言管理</h2><p>查看商品咨询并回复用户留言</p></div></div><div class="table-card"><div class="table-caption">商品留言 <span>共 {{adminTotals.messages}} 条</span></div><div class="data-row data-head report-columns"><span>留言内容</span><span>用户</span><span>商品</span><span>状态</span><span>操作</span></div><div v-for="message in filteredMessages" :key="message.id" class="data-row report-columns"><div><strong>{{message.content}}</strong><small>留言 #{{message.id}} · {{formatDate(message.createdAt)}}</small><small v-if="message.replyContent">回复：{{message.replyContent}}</small></div><span>{{message.userName}}</span><span>商品 #{{message.goodsId}}</span><el-tag size="small" :type="message.status==='REPLIED'?'success':'warning'">{{message.status==='REPLIED'?'已回复':'待回复'}}</el-tag><button class="row-action" @click="replyMessage(message)">{{message.status==='REPLIED'?'修改回复':'回复留言'}}</button></div><div v-if="!filteredMessages.length" class="table-empty">暂无留言记录</div></div></section>
<section v-else-if="tab==='wants'" class="workspace"><div class="section-toolbar"><div><h2>求购审核</h2><p>审核用户发布的求购信息，维护求购大厅内容</p></div><el-select v-model="wantStatus" placeholder="全部状态" clearable><el-option label="审核中" value="PENDING"/><el-option label="求购中" value="PUBLISHED"/><el-option label="已隐藏" value="HIDDEN"/><el-option label="已找到" value="FOUND"/><el-option label="已撤回" value="WITHDRAWN"/></el-select></div><div class="table-card"><div class="table-caption">求购信息 <span>共 {{adminTotals.wants}} 条</span></div><div class="data-row data-head report-columns"><span>求购内容</span><span>发布人</span><span>分类</span><span>状态</span><span>操作</span></div><div v-for="want in filteredWants" :key="want.id" class="data-row report-columns"><div><strong>{{want.title}}</strong><small>{{want.description}} · 预算 {{want.budget||'面议'}}</small></div><span>{{want.requesterName}}</span><span>{{want.category}}</span><el-tag size="small" :type="want.status==='PUBLISHED'?'success':want.status==='PENDING'?'warning':'info'">{{wantStatusLabel(want.status)}}</el-tag><button v-if="['PENDING','PUBLISHED','HIDDEN'].includes(want.status)" class="row-action" @click="toggleWant(want)">{{want.status==='PUBLISHED'?'隐藏信息':'通过审核'}}</button></div><div v-if="!filteredWants.length" class="table-empty">暂无求购信息</div></div></section>
<section v-else class="workspace"><div class="section-toolbar"><div><h2>举报中心</h2><p>处理商品和用户的违规反馈</p></div><el-select v-model="reportStatus" placeholder="全部状态" clearable><el-option label="待处理" value="PENDING"/><el-option label="已处理" value="RESOLVED"/><el-option label="已忽略" value="IGNORED"/></el-select></div><div class="table-card"><div class="table-caption">举报记录 <span>共 {{adminTotals.reports}} 条</span></div><div class="data-row data-head report-columns"><span>举报内容</span><span>举报人</span><span>对象</span><span>状态</span><span>操作</span></div><div v-for="report in filteredReports" :key="report.id" class="data-row report-columns"><div><strong>{{report.reason}}</strong><small>举报编号 #{{report.id}} · {{formatDate(report.createdAt)}}</small></div><span>{{report.reporterName}}</span><span>{{report.targetType==='GOODS'?'商品 #':'用户 #'}}{{report.targetId}}</span><el-tag size="small" :type="report.status==='PENDING'?'warning':'info'">{{reportStatusLabel(report.status)}}</el-tag><div><button v-if="report.status==='PENDING'" class="row-action" @click="resolveReport(report,'RESOLVED')">处理完成</button><button v-if="report.status==='PENDING'" class="row-action muted" @click="resolveReport(report,'IGNORED')">忽略</button></div></div><div v-if="!filteredReports.length" class="table-empty">暂无举报记录</div></div></section>
      </template>
      <div class="admin-pagination"><el-pagination v-model:current-page="currentAdminPage" v-model:page-size="adminPageSize" :page-sizes="[4,8,16,32]" :disabled="loading" :total="adminTotalForCurrent" layout="total, sizes, prev, pager, next, jumper" background/></div>
    </main>
  </section>
</template>

<script setup>
import {computed, onMounted, reactive, ref, watch} from 'vue'
import axios from 'axios'
import PageBanner from './PageBanner.vue'
import ProductImage from './ProductImage.vue'
import {ElMessage, ElMessageBox} from 'element-plus'
const emit=defineEmits(['back'])
const currentUser=JSON.parse(localStorage.getItem('campus-user')||'null'), userName=currentUser?.nickname||'管理员'
const tab=ref('overview'), loading=ref(false), goods=ref([]), users=ref([]), orders=ref([]), reports=ref([]), messages=ref([]), wants=ref([]), goodsKeyword=ref(''), userKeyword=ref(''), goodsStatus=ref(''), orderStatus=ref(''), reportStatus=ref(''), wantStatus=ref('')
const adminPageSize=ref(8), adminPages=reactive({goods:1,users:1,orders:1,messages:1,wants:1,reports:1}), adminTotals=reactive({goods:0,users:0,orders:0,messages:0,wants:0,reports:0})
const stats=ref({goods:0,onSale:0,orders:0,pendingOrders:0,pendingReports:0,pendingWants:0,offShelf:0,activeUsers:0})
const menus=[{key:'overview',icon:'⌂',label:'运营概览',description:'查看平台当前运行状态',eyebrow:'OVERVIEW'},{key:'goods',icon:'▦',label:'商品审核',description:'管理商品状态和违规内容',eyebrow:'GOODS'},{key:'users',icon:'♙',label:'用户管理',description:'维护账号状态和平台角色',eyebrow:'USERS'},{key:'orders',icon:'◇',label:'订单监管',description:'跟踪购买意向和交易状态',eyebrow:'ORDERS'},{key:'messages',icon:'✦',label:'留言管理',description:'处理商品咨询和卖家回复',eyebrow:'MESSAGES'},{key:'wants',icon:'⌕',label:'求购审核',description:'审核校园求购信息',eyebrow:'WANTS'},{key:'reports',icon:'!',label:'举报中心',description:'处理商品和用户的违规反馈',eyebrow:'REPORTS'}]
const activeMenu=computed(()=>menus.find(item=>item.key===tab.value)||menus[0])
const filteredGoods=computed(()=>goods.value)
const filteredUsers=computed(()=>users.value)
const filteredOrders=computed(()=>orders.value)
const filteredReports=computed(()=>reports.value)
const filteredMessages=computed(()=>messages.value)
const filteredWants=computed(()=>wants.value)
const currentPageKey=computed(()=>tab.value==='overview'?'goods':tab.value)
const currentAdminPage=computed({get:()=>adminPages[currentPageKey.value]||1,set:value=>{adminPages[currentPageKey.value]=value}})
const adminTotalForCurrent=computed(()=>adminTotals[currentPageKey.value]||0)
function headers(){return {headers:{'X-User-Role':currentUser?.role||'USER'}}}
const aliases={ID:'id',TITLE:'title',PRICE:'price',CATEGORY:'category',CONDITIONLEVEL:'conditionLevel',LOCATION:'location',DESCRIPTION:'description',IMAGEURL:'imageUrl',SELLERNAME:'sellerName',STATUS:'status',FAVORITECOUNT:'favoriteCount',CREATEDAT:'createdAt',USERNAME:'username',NICKNAME:'nickname',ROLE:'role',GOODSID:'goodsId',BUYERNAME:'buyerName',REPORTERNAME:'reporterName',TARGETTYPE:'targetType',TARGETID:'targetId',REASON:'reason',USERID:'userId',MESSAGEUSERNAME:'userName',CONTENT:'content',REPLYCONTENT:'replyContent',REPLYNAME:'replyName',REPLIEDAT:'repliedAt',REQUESTERNAME:'requesterName',BUDGET:'budget'}
function normalize(row){return Object.fromEntries(Object.entries(row).map(([key,value])=>[aliases[key]||key,value]))}
async function get(url){const data=(await axios.get(url,headers())).data.data;return normalize(data)}
async function getPage(key){
  const params={page:adminPages[key],size:adminPageSize.value}
  if(tab.value!=='overview'){
    if(key==='goods'){params.keyword=goodsKeyword.value;params.status=goodsStatus.value}
    if(key==='users')params.keyword=userKeyword.value
    if(key==='orders')params.status=orderStatus.value
    if(key==='reports')params.status=reportStatus.value
    if(key==='wants')params.status=wantStatus.value
  }
  const data=(await axios.get('/api/admin/'+key,{...headers(),params})).data.data
  return {records:data.records.map(normalize),total:data.total}
}
let adminRequest=0
async function loadCurrent(){
  const requestId=++adminRequest,key=currentPageKey.value
  loading.value=true
  try{
    const [overview,data]=await Promise.all([get('/api/admin/overview'),getPage(key)])
    if(requestId!==adminRequest)return
    stats.value=overview;adminTotals[key]=data.total
    const lastPage=Math.max(1,Math.ceil(data.total/adminPageSize.value))
    if(adminPages[key]>lastPage){adminPages[key]=lastPage;return}
    const lists={goods,users,orders,reports,messages,wants};lists[key].value=data.records
  }catch(error){if(requestId===adminRequest)ElMessage.error(error.response?.data?.message||'后台数据加载失败')}finally{if(requestId===adminRequest)loading.value=false}
}
function selectTab(key){if(tab.value===key){loadCurrent();return}tab.value=key;adminPages[key==='overview'?'goods':key]=1}
async function toggleGoods(item){const value=item.status==='ON_SALE'?'OFF_SHELF':'ON_SALE';await axios.patch(`/api/admin/goods/${item.id}/status`,null,{...headers(),params:{value}});item.status=value;await loadCurrent();ElMessage.success('商品状态已更新')}
async function toggleUser(user){const value=user.status===1?0:1;await axios.patch(`/api/admin/users/${user.id}/status`,null,{...headers(),params:{value}});user.status=value;await loadCurrent();ElMessage.success(value===1?'账号已恢复':'账号已禁用')}
async function completeOrder(order){await axios.patch(`/api/admin/orders/${order.id}/status`,null,{...headers(),params:{value:'COMPLETED'}});order.status='COMPLETED';await loadCurrent();ElMessage.success('订单已标记完成')}
async function resolveReport(report,status){await axios.patch(`/api/admin/reports/${report.id}/status`,null,{...headers(),params:{value:status}});report.status=status;await loadCurrent();ElMessage.success(status==='RESOLVED'?'举报已处理':'举报已忽略')}
async function replyMessage(message){try{const {value}=await ElMessageBox.prompt(message.content,'回复商品留言',{inputType:'textarea',inputValue:message.replyContent||'',confirmButtonText:'发送回复',cancelButtonText:'取消',inputValidator:content=>!!content?.trim()&&content.trim().length<=500||'请输入 1 至 500 字的回复'});await axios.patch(`/api/admin/messages/${message.id}/reply`,{content:value.trim()},headers());message.replyContent=value.trim();message.replyName='管理员';message.status='REPLIED';ElMessage.success('留言已回复')}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(error.response?.data?.message||'回复失败，请重试')}}
async function toggleWant(want){try{const value=want.status==='PUBLISHED'?'HIDDEN':'PUBLISHED';await axios.patch(`/api/admin/wants/${want.id}/status`,null,{...headers(),params:{value}});want.status=value;await loadCurrent();ElMessage.success(value==='PUBLISHED'?'求购信息已通过':'求购信息已隐藏')}catch(error){ElMessage.error(error.response?.data?.message||'审核失败，请刷新列表')}}

function statusLabel(value){return {ON_SALE:'在售',OFF_SHELF:'已下架',RESERVED:'已预订',SOLD:'已售出'}[value]||value}
function orderStatusLabel(value){return {PENDING:'待确认',COMPLETED:'已完成',CANCELLED:'已取消'}[value]||value}
function reportStatusLabel(value){return {PENDING:'待处理',RESOLVED:'已处理',IGNORED:'已忽略'}[value]||value}
function wantStatusLabel(value){return {PENDING:'审核中',PUBLISHED:'求购中',HIDDEN:'已隐藏',FOUND:'已找到',WITHDRAWN:'已撤回'}[value]||value}
function formatDate(value){return value?new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):''}
watch([tab,currentAdminPage,adminPageSize,goodsKeyword,goodsStatus,userKeyword,orderStatus,reportStatus,wantStatus],(next,previous)=>{if(next.some((value,index)=>index!==1&&value!==previous[index])&&currentAdminPage.value!==1){currentAdminPage.value=1;return}loadCurrent()})
onMounted(loadCurrent)
</script>

